    {
      "step": 1,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "VIDEO",
        "query": "geometry problem screen showing a circle divided into equal pieces with answer choices and measurement labels",
        "timestamps": null,
        "num_frames": 3
      },
      "purpose": "Retrieve candidate problem frames containing the circle diagram and any visible numeric labels needed for the perimeter calculation.",
      "depends_on": []
    },
    {
      "step": 2,
      "tool": "ocr",
      "arguments": {
        "frame_path": "<STEP_1:frames>",
        "timestamp": null
      },
      "purpose": "Extract the on-screen text from the candidate problem frames, including any radius, diameter, circumference, or other numeric labels and the answer options.",
      "depends_on": [
        1
      ]
    }
  ],
  "refinement_instructions": "Build the new trace from scratch. Use the retrieved frame bundle and OCR output to identify the frame that actually contains the asked circle problem. Quote the grounded visible givens from that frame only; do not invent unseen measurements. The rewritten trace should explicitly state the diagram facts read from OCR (for example radius/diameter/circumference labels and that the circle is divided into 12 equal pieces), then compute one piece's perimeter as two radii plus the arc length of 1/12 of the full circumference. If the grounded measurement is radius r, use perimeter = 2r + (2πr)/12; if the grounded measurement is diameter d or full circumference C, convert appropriately before computing. Then compare the computed value to the listed options and update the final answer accordingly. If OCR across the three frames differs, select the frame-level OCR result that clearly shows the full problem statement and choices; do not merge mixed or partial readings from different phases unless they are visually the same problem screen."
}

